#include <iostream>
using namespace std;

typedef struct
{
    int iNumber;
    int iScore;
}Student;

int main()
{
    Student tArr[3];

    for (int i = 0; i < 3; ++i)
    {
        tArr[i].iNumber = i + 1;
        cin >> tArr[i].iScore;
    }

    int iMaxIndex = 0;

    for (int i = 1; i < 3; ++i)
    {
        if (tArr[i].iScore > tArr[iMaxIndex].iScore)
        {
            iMaxIndex = i;
        }
    }

    cout << "최고 점수: " << tArr[iMaxIndex].iScore << endl;
    cout << "학생 번호: " << tArr[iMaxIndex].iNumber << endl;

    return 0;
}
